<?php

namespace App\OpenApi;

use App\Exceptions\ApiDocumentUnavailableException;
use Closure;
use Illuminate\Support\Facades\File;
use L5Swagger\ConfigFactory;
use L5Swagger\GeneratorFactory;
use Throwable;

/**
 * The engine's OpenAPI 3 document, the one `l5-swagger:generate` writes, generated by the same generator on first use
 * and kept beside it as `engine-<version>.json` until the engine's version changes. Generation runs under a lock into a
 * directory of its own, and only a complete, parsed document replaces the cached one.
 */
class EngineApiDocument
{
    private const GENERATED = 'api-docs.json';

    public function json(): string
    {
        try {
            return $this->cached() ?? $this->underLock(fn (): string => $this->cached() ?? $this->regenerate());
        } catch (ApiDocumentUnavailableException $e) {
            throw $e;
        } catch (Throwable $e) {
            throw new ApiDocumentUnavailableException($e->getMessage(), $e);
        }
    }

    public function path(): string
    {
        return $this->directory().DIRECTORY_SEPARATOR.'engine-'.$this->version().'.json';
    }

    /** @phpstan-impure */
    private function cached(): ?string
    {
        $path = $this->path();

        if (! is_file($path)) {
            return null;
        }

        $json = file_get_contents($path);

        return is_string($json) && $json !== '' ? $json : null;
    }

    /** @param Closure(): string $work */
    private function underLock(Closure $work): string
    {
        $this->ensureWritable($this->directory());
        $lock = fopen($this->directory().DIRECTORY_SEPARATOR.'engine.lock', 'c');

        if ($lock === false || ! flock($lock, LOCK_EX)) {
            throw new ApiDocumentUnavailableException('the lock in '.$this->directory().' could not be taken');
        }

        try {
            return $work();
        } finally {
            flock($lock, LOCK_UN);
            fclose($lock);
        }
    }

    private function regenerate(): string
    {
        $workdir = $this->directory().DIRECTORY_SEPARATOR.'.generating-'.bin2hex(random_bytes(6));

        try {
            $this->generateInto($workdir);
            $json = $this->validated((string) File::get($workdir.DIRECTORY_SEPARATOR.self::GENERATED));
            $this->store($json);
        } finally {
            File::deleteDirectory($workdir);
        }

        $this->forgetOtherVersions();

        return $json;
    }

    private function generateInto(string $workdir): void
    {
        $configs = new class($workdir, self::GENERATED) extends ConfigFactory
        {
            public function __construct(private readonly string $workdir, private readonly string $file) {}

            /** @return array<string, mixed> */
            public function documentationConfig(?string $documentation = null): array
            {
                $config = parent::documentationConfig($documentation);
                $config['paths']['docs'] = $this->workdir;
                $config['paths']['docs_json'] = $this->file;
                $config['generate_yaml_copy'] = false;

                return $config;
            }
        };

        (new GeneratorFactory($configs))->make((string) config('l5-swagger.default'))->generateDocs();
    }

    private function validated(string $json): string
    {
        $document = json_decode($json, true);

        if (! is_array($document) || ! is_string($document['openapi'] ?? null) || ! is_array($document['paths'] ?? null) || $document['paths'] === []) {
            throw new ApiDocumentUnavailableException('the generator wrote no OpenAPI document with paths');
        }

        return $json;
    }

    private function store(string $json): void
    {
        $partial = $this->path().'.'.bin2hex(random_bytes(6)).'.partial';

        if (file_put_contents($partial, $json) !== strlen($json) || ! rename($partial, $this->path())) {
            File::delete($partial);

            throw new ApiDocumentUnavailableException($this->path().' could not be written');
        }
    }

    private function forgetOtherVersions(): void
    {
        foreach (File::glob($this->directory().DIRECTORY_SEPARATOR.'engine-*.json') as $file) {
            if ($file !== $this->path()) {
                File::delete($file);
            }
        }
    }

    private function ensureWritable(string $directory): void
    {
        if (! is_dir($directory) && ! @mkdir($directory, 0775, true) && ! is_dir($directory)) {
            throw new ApiDocumentUnavailableException($directory.' could not be created');
        }

        if (! is_writable($directory)) {
            throw new ApiDocumentUnavailableException($directory.' is not writable');
        }
    }

    private function directory(): string
    {
        return rtrim((string) (new ConfigFactory)->documentationConfig()['paths']['docs'], DIRECTORY_SEPARATOR);
    }

    private function version(): string
    {
        $version = preg_replace('/[^A-Za-z0-9._-]+/', '-', (string) config('system.version', ''));

        return $version === null || $version === '' ? 'unknown' : $version;
    }
}
